-- ===========================================
-- Phase 10: Logs/Audit Tables
-- ===========================================

-- AuditLogs table
CREATE TABLE public."AuditLogs" (
  "AuditID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "UserName" VARCHAR(100),
  "Action" VARCHAR(100),
  "Module" VARCHAR(100),
  "TableName" VARCHAR(100),
  "RecordID" VARCHAR(100),
  "CompanyID" INTEGER,
  "EmployeeID" INTEGER,
  "C3HeaderID" INTEGER,
  "RegNumber" VARCHAR(50),
  "Period_Year" VARCHAR(10),
  "Period_Month" VARCHAR(10),
  "OldValues" TEXT,
  "NewValues" TEXT,
  "Description" TEXT,
  "IPAddress" VARCHAR(50),
  "BrowserInfo" VARCHAR(500),
  "MachineInfo" VARCHAR(500),
  "ActionDate" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "IsActive" BOOLEAN DEFAULT TRUE
);

-- LoginLog table
CREATE TABLE public."LoginLog" (
  "LogID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "LoginID" VARCHAR(100),
  "LoginTime" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "LogoutTime" TIMESTAMP WITH TIME ZONE,
  "IPAddress" VARCHAR(50),
  "MachineInfo" VARCHAR(500),
  "IsActive" BOOLEAN DEFAULT TRUE
);

-- CustomErrorLogs table
CREATE TABLE public."CustomErrorLogs" (
  "ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "ErrorType" VARCHAR(100),
  "ErrorMessage" TEXT,
  "StackTrace" TEXT,
  "MachineInfo" VARCHAR(500),
  "ErrorDate" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ErrorLog table
CREATE TABLE public."ErrorLog" (
  "ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "PageURL" VARCHAR(500),
  "ErrorMessage" TEXT,
  "ErrorStack" TEXT,
  "ErrorTime" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Exception_log table
CREATE TABLE public."Exception_log" (
  "ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "ExceptionType" VARCHAR(200),
  "ExceptionMessage" TEXT,
  "StackTrace" TEXT,
  "InnerException" TEXT,
  "Source" VARCHAR(200),
  "MethodName" VARCHAR(200),
  "MachineInfo" VARCHAR(500),
  "AdditionalInfo" TEXT,
  "ExceptionDate" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ContactUs_Log table
CREATE TABLE public."ContactUs_Log" (
  "CUS_ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "CompanyID" INTEGER,
  "RegistrationNo" INTEGER,
  "Name" VARCHAR(200),
  "EmailID" VARCHAR(200),
  "Phone" VARCHAR(50),
  "Subject" VARCHAR(500),
  "Description" TEXT,
  "Status" VARCHAR(50),
  "InsertDate" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertMachineInfo" VARCHAR(500)
);

-- ===========================================
-- Phase 11: Payment Tables
-- ===========================================

-- OnlinePayments table
CREATE TABLE public."OnlinePayments" (
  "PaymentID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "TransactionID" VARCHAR(100),
  "ReferenceNumber" VARCHAR(100),
  "CompanyID" INTEGER,
  "SelfEmployeeID" INTEGER,
  "C3HeaderID" INTEGER,
  "SelfC3ID" INTEGER,
  "PaymentType" VARCHAR(50),
  "PaymentMethod" VARCHAR(50),
  "Amount" NUMERIC(18,2),
  "Currency" VARCHAR(10) DEFAULT 'BBD',
  "Status" VARCHAR(50),
  "PaymentDate" TIMESTAMP WITH TIME ZONE,
  "Period_Year" VARCHAR(10),
  "Period_Month" VARCHAR(10),
  "CardType" VARCHAR(50),
  "CardLastFour" VARCHAR(10),
  "CardHolderName" VARCHAR(200),
  "BillingAddress1" VARCHAR(500),
  "BillingAddress2" VARCHAR(500),
  "BillingCity" VARCHAR(100),
  "BillingState" VARCHAR(100),
  "BillingZip" VARCHAR(20),
  "BillingCountry" VARCHAR(100),
  "ResponseCode" VARCHAR(50),
  "ResponseMessage" TEXT,
  "AuthCode" VARCHAR(100),
  "CyberSourceRequestID" VARCHAR(100),
  "CyberSourceDecision" VARCHAR(50),
  "CyberSourceReasonCode" VARCHAR(50),
  "IPAddress" VARCHAR(50),
  "MachineInfo" VARCHAR(500),
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(500),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(500),
  "IsReconciled" BOOLEAN DEFAULT FALSE,
  "ReconciledDate" TIMESTAMP WITH TIME ZONE,
  "ReconciledBy" INTEGER,
  "Remarks" TEXT,
  "ErrorMessage" TEXT,
  "RetryCount" INTEGER DEFAULT 0,
  "Email" VARCHAR(200),
  "Phone" VARCHAR(50),
  "FirstName" VARCHAR(100),
  "LastName" VARCHAR(100),
  "CompanyName" VARCHAR(200),
  "RegNumber" VARCHAR(50),
  "SSN" VARCHAR(50),
  "PayerType" VARCHAR(50),
  "ReceiptNumber" VARCHAR(100),
  "ReceiptURL" VARCHAR(500),
  "IsRefunded" BOOLEAN DEFAULT FALSE,
  "RefundDate" TIMESTAMP WITH TIME ZONE,
  "RefundAmount" NUMERIC(18,2),
  "RefundReason" TEXT,
  "RefundTransactionID" VARCHAR(100)
);

-- BankPaymentsMain table
CREATE TABLE public."BankPaymentsMain" (
  "ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "CompanyID" INTEGER,
  "BankName" VARCHAR(200),
  "CheckNumber" VARCHAR(50),
  "CheckDate" TIMESTAMP WITH TIME ZONE,
  "Amount" NUMERIC(18,2),
  "IsActive" BOOLEAN DEFAULT TRUE
);

-- UserCardDetail table
CREATE TABLE public."UserCardDetail" (
  "CardDetailID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "UserID" INTEGER,
  "CardToken" VARCHAR(500),
  "CardType" VARCHAR(50),
  "CardLastFour" VARCHAR(10),
  "CardHolderName" VARCHAR(200),
  "ExpiryMonth" VARCHAR(2),
  "ExpiryYear" VARCHAR(4),
  "IsDefault" BOOLEAN DEFAULT FALSE,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Reconciliation_Cyber_Space table
CREATE TABLE public."Reconciliation_Cyber_Space" (
  "ReconID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "FileName" VARCHAR(500),
  "FileDate" TIMESTAMP WITH TIME ZONE,
  "TotalRecords" INTEGER,
  "TotalAmount" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "ProcessedDate" TIMESTAMP WITH TIME ZONE,
  "ProcessedBy" INTEGER,
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(500),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(500)
);

-- Reconciliation_Cyber_Space_Column table
CREATE TABLE public."Reconciliation_Cyber_Space_Column" (
  "ColumnID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "ReconID" INTEGER REFERENCES public."Reconciliation_Cyber_Space"("ReconID"),
  "ColumnName" VARCHAR(100),
  "ColumnValue" TEXT,
  "RowNumber" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ReconciliationPayment_Details table
CREATE TABLE public."ReconciliationPayment_Details" (
  "DetailID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "ReconID" INTEGER REFERENCES public."Reconciliation_Cyber_Space"("ReconID"),
  "PaymentID" INTEGER REFERENCES public."OnlinePayments"("PaymentID"),
  "TransactionID" VARCHAR(100),
  "Amount" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "MatchDate" TIMESTAMP WITH TIME ZONE,
  "Remarks" TEXT,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- ===========================================
-- Phase 12: CMS/Content Tables
-- ===========================================

-- AboutUs table
CREATE TABLE public."AboutUs" (
  "ID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "Content" TEXT
);

